def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_D = 0
    my_D = 0
    for m, o in history:
        if o == 'D':
            opp_D += 1
        if m == 'D':
            my_D += 1

    opp_C = n - opp_D

    if opp_D == n:
        return 'D'

    last6 = history[-6:]
    rec6_D = 0
    for m, o in last6:
        if o == 'D':
            rec6_D += 1

    mutual_D_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            mutual_D_streak += 1
        else:
            break

    failed_recovery = False
    if n >= 3:
        start = max(1, n - 24)
        for j in range(start, n - 1):
            if history[j] == ('C', 'D') and history[j - 1] == ('D', 'D') and history[j + 1][1] == 'D':
                failed_recovery = True
                break

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2:
                pm, po = history[-2]
                if pm == 'D' and po == 'C':
                    if n >= 10 and rec6_D <= 2 and opp_D <= max(2, n // 10) and opp_C * 5 >= n * 4:
                        return 'C'
                if pm == 'D' and po == 'D':
                    if not failed_recovery and opp_C > 0:
                        return 'C'
        else:
            if not failed_recovery and opp_C * 5 >= n * 2:
                if mutual_D_streak >= 5:
                    return 'C'
                if mutual_D_streak >= 3 and rng.random() < 0.5:
                    return 'C'
            return 'D'

        return 'D'

    if my_last == 'D':
        if n >= 2:
            pm, po = history[-2]
            if pm == 'C' and po == 'D':
                return 'C'

        if opp_D == 0 or rec6_D >= 2 or (my_D > opp_D + 1 and opp_D <= max(2, n // 10)):
            return 'D'

        return 'C'

    return 'C'
